INSERT INTO aulas (id_status, id_professor, id_turma, assunto, vocabulario, saldo, observacoes, data_aula, data_aula_original, data_aula_solicitada)
SELECT 2, @usr_teacher_mariana, @tur_legacy_mariana_lucas_mota_felipe, NULL, NULL, 'Fizemos uma atividade sobre school supplies ao final da aula - trabalhamos as palavras eraser, ruler, school bag, scissors, book, glue.', 'Estava um pouco cansado e aula mais "pesada" contribuiu para o desânimo, no entanto, teve um bom desempenho. Lucas levantou ótimas respostas e hipóteses na atividade "letters and sounds" - como em "FI" para Fish e "LI" para Lemon. Notei, em alguns momentos, Lucas tentando copiar as respostas do Tiago ou esperando-as prontas vindas do irmão. Ambos os meninos ficaram confusos, por vezes, com o fonema /t/ e fizeram tentativas de escrita com o número 2 "two" (em turtle, por exemplo) depois mudaram suas respostas. Notei também, que basearam seus conhecimentos no português e tentaram aplicar os mesmos fonemas para o inglês - o que acredito fazer parte da fase de desenvolvimento e alfabetização de ambos. Os meninos fizeram a atividade de "letters and sounds" em 8''39'''' e de "spelling" em 29''47'''' - Lucas terminou um pouco mais rápido do que Tiago mas tentou, por vezes, "adivinhar" a escrita mais do que explorar o som das palavras. Na atividade de fonemas repetiram comigo os fonemas algumas vezes e levantaram algumas hipóteses como happy for /c/ /l/ /a/ /p/ and six for /m/ /i/ /x/. Segmenting phonemes foi um pouco mais difícil, os meninos separaram mais as sílabas do que os sons.', '2022-03-07 00:00:00', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM aulas WHERE id_turma = @tur_legacy_mariana_lucas_mota_felipe AND data_aula = '2022-03-07 00:00:00' AND COALESCE(assunto, '') = COALESCE(NULL, '') AND COALESCE(saldo, '') = COALESCE('Fizemos uma atividade sobre school supplies ao final da aula - trabalhamos as palavras eraser, ruler, school bag, scissors, book, glue.', '') AND COALESCE(observacoes, '') = COALESCE('Estava um pouco cansado e aula mais "pesada" contribuiu para o desânimo, no entanto, teve um bom desempenho. Lucas levantou ótimas respostas e hipóteses na atividade "letters and sounds" - como em "FI" para Fish e "LI" para Lemon. Notei, em alguns momentos, Lucas tentando copiar as respostas do Tiago ou esperando-as prontas vindas do irmão. Ambos os meninos ficaram confusos, por vezes, com o fonema /t/ e fizeram tentativas de escrita com o número 2 "two" (em turtle, por exemplo) depois mudaram suas respostas. Notei também, que basearam seus conhecimentos no português e tentaram aplicar os mesmos fonemas para o inglês - o que acredito fazer parte da fase de desenvolvimento e alfabetização de ambos. Os meninos fizeram a atividade de "letters and sounds" em 8''39'''' e de "spelling" em 29''47'''' - Lucas terminou um pouco mais rápido do que Tiago mas tentou, por vezes, "adivinhar" a escrita mais do que explorar o som das palavras. Na atividade de fonemas repetiram comigo os fonemas algumas vezes e levantaram algumas hipóteses como happy for /c/ /l/ /a/ /p/ and six for /m/ /i/ /x/. Segmenting phonemes foi um pouco mais difícil, os meninos separaram mais as sílabas do que os sons.', ''));

