INSERT INTO aulas (id_status, id_professor, id_turma, assunto, vocabulario, saldo, observacoes, data_aula, data_aula_original, data_aula_solicitada)
SELECT 2, @usr_teacher_mariana_luiza_secco, @tur_legacy_mariana_luiza_secco_marina_franca, 'Aula Ok!', NULL, 'Desde quando eu cheguei na casa das irmãs a Olivia estava chorando muito, a mãe a levou para o quarto o que só piorou e fez com que ela chorasse mais e ficasse mais frustrada. Por consequência, a Marina ficou muito nervosa, colocava as mãos no ouvido e dizia que não aguentava mais a gritaria, a saída foi passar a aula fazendo brincadeiras com música para distrair a Marina, como dançar freeze, mímica e coreografias. Consegui fazer o Mabi com a Marina, mas a Olivia não participou de nenhum momento da aula.', NULL, '2025-02-28 00:00:00', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM aulas WHERE id_turma = @tur_legacy_mariana_luiza_secco_marina_franca AND data_aula = '2025-02-28 00:00:00' AND COALESCE(assunto, '') = COALESCE('Aula Ok!', '') AND COALESCE(saldo, '') = COALESCE('Desde quando eu cheguei na casa das irmãs a Olivia estava chorando muito, a mãe a levou para o quarto o que só piorou e fez com que ela chorasse mais e ficasse mais frustrada. Por consequência, a Marina ficou muito nervosa, colocava as mãos no ouvido e dizia que não aguentava mais a gritaria, a saída foi passar a aula fazendo brincadeiras com música para distrair a Marina, como dançar freeze, mímica e coreografias. Consegui fazer o Mabi com a Marina, mas a Olivia não participou de nenhum momento da aula.', '') AND COALESCE(observacoes, '') = COALESCE(NULL, ''));

