INSERT INTO aulas (id_status, id_professor, id_turma, assunto, vocabulario, saldo, observacoes, data_aula, data_aula_original, data_aula_solicitada)
SELECT 2, @usr_teacher_yasmin_dos_santos_mello, @tur_legacy_yasmin_dos_santos_mello_escola_ka, 'Aula Ok!', NULL, 'A escola estava um tanto caótica acredito que por ser a última semana de aula. Cheguei na sala (infantil 3) não tinham mesas nem cadeiras, fui direcionada a outra sala em que as mesas estavam todas bagunçadas e empilhadas, além das crianças nunca estarem com seus estojos, situações que fazem com que a aula demore para ser iniciada, prejudicando o tempo total de aula e o conteúdo dado.', NULL, '2025-07-02 00:00:00', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM aulas WHERE id_turma = @tur_legacy_yasmin_dos_santos_mello_escola_ka AND data_aula = '2025-07-02 00:00:00' AND COALESCE(assunto, '') = COALESCE('Aula Ok!', '') AND COALESCE(saldo, '') = COALESCE('A escola estava um tanto caótica acredito que por ser a última semana de aula. Cheguei na sala (infantil 3) não tinham mesas nem cadeiras, fui direcionada a outra sala em que as mesas estavam todas bagunçadas e empilhadas, além das crianças nunca estarem com seus estojos, situações que fazem com que a aula demore para ser iniciada, prejudicando o tempo total de aula e o conteúdo dado.', '') AND COALESCE(observacoes, '') = COALESCE(NULL, ''));

