SELECT 2, @usr_teacher_monica_schreiber, @tur_legacy_monica_schreiber_luisa_malucelli, 'Aula Ok!', NULL, 'A Luisa já estava cansada durante a aula, e em determinado momento a mãe interrompeu para pedir que ela fizesse uma parte da aula da Lívia, pois a Lívia também estava cansada para participar do inglês. A partir desse momento, ficou bem difícil continuar, já que a Luisa ficou bastante chateada. Mesmo mantendo o tempo normal da aula, o clima não foi o mesmo, especialmente porque hoje foi a Reward Class da Lívia.', NULL, '2025-08-18 00:00:00', NULL, NULL
WHERE NOT EXISTS (SELECT 1 FROM aulas WHERE id_turma = @tur_legacy_monica_schreiber_luisa_malucelli AND data_aula = '2025-08-18 00:00:00' AND COALESCE(assunto, '') = COALESCE('Aula Ok!', '') AND COALESCE(saldo, '') = COALESCE('A Luisa já estava cansada durante a aula, e em determinado momento a mãe interrompeu para pedir que ela fizesse uma parte da aula da Lívia, pois a Lívia também estava cansada para participar do inglês. A partir desse momento, ficou bem difícil continuar, já que a Luisa ficou bastante chateada. Mesmo mantendo o tempo normal da aula, o clima não foi o mesmo, especialmente porque hoje foi a Reward Class da Lívia.', '') AND COALESCE(observacoes, '') = COALESCE(NULL, ''));

